arguments.file_text:
@page "/chat"
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout @(IsThreadOpen ? "thread-open" : "")">
    <ChannelSidebar Channels="_channels"
                    ActiveChannelId="_activeChannelId"
                    OnChannelSelected="SelectChannel" />

    <MessageArea ChannelName="@ActiveChannel?.Name"
                 ChannelDescription="@ActiveChannel?.Description"
                 Messages="_messages"
                 ThreadSummaries="_threadSummaries"
                 IsLoadingMore="_isLoadingMore"
                 OnLoadMore="LoadMoreMessages"
                 OnSendMessage="SendMessage"
                 OnOpenThread="OpenThread"
                 OnReact="HandleReaction" />

    @if (IsThreadOpen)
    {
        <ThreadPanel RootMessage="_threadRootMessage"
                     Replies="_threadReplies"
                     OnClose="CloseThread"
                     OnSendReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> _channels = [];
    private List<Message> _messages = [];
    private List<ThreadSummary> _threadSummaries = [];
    private int _activeChannelId;
    private bool _isLoadingMore;
    private const int PageSize = 30;

    // Thread state
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = [];

    private bool IsThreadOpen => _threadRootMessage is not null;
    private Channel? ActiveChannel => _channels.FirstOrDefault(c => c.Id == _activeChannelId);

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _activeChannelId = channelId;
        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _threadSummaries = BuildThreadSummaries(_messages);
        await ChatService.MarkChannelReadAsync(channelId);

        // Update unread count locally
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            var ch = _channels[idx];
            _channels[idx] = ch with { UnreadCount = 0 };
        }

        // Close thread if switching channels
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task LoadMoreMessages()
    {
        if (_isLoadingMore) return;
        _isLoadingMore = true;

        var older = await ChatService.GetMessagesAsync(_activeChannelId, _messages.Count, PageSize);
        if (older.Count > 0)
        {
            _messages.InsertRange(0, older);
            _threadSummaries = BuildThreadSummaries(_messages);
        }

        _isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        var msg = await ChatService.SendMessageAsync(_activeChannelId, content, null);
        _messages.Add(msg);
    }

    private async Task OpenThread(int messageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
        if (_threadRootMessage is not null)
        {
            var thread = await ChatService.GetThreadAsync(messageId);
            _threadReplies = thread.Where(m => m.Id != messageId).ToList();
        }
    }

    private void CloseThread()
    {
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (_threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(_activeChannelId, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);

        // Update thread summary in main view
        _threadSummaries = BuildThreadSummaries(_messages, _threadRootMessage.Id, _threadReplies.Count, reply.SentAt);
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Optimistically update the message's reaction list
        var msgIdx = _messages.FindIndex(m => m.Id == args.MessageId);
        if (msgIdx >= 0)
        {
            var msg = _messages[msgIdx];
            var reactions = msg.Reactions.ToList();
            var existing = reactions.FindIndex(r => r.Emoji == args.Emoji);
            if (existing >= 0)
            {
                var r = reactions[existing];
                reactions[existing] = new Reaction(r.Emoji, [..r.Users, "You"]);
            }
            else
            {
                reactions.Add(new Reaction(args.Emoji, ["You"]));
            }
            _messages[msgIdx] = msg with { Reactions = reactions };
        }
    }

    private static List<ThreadSummary> BuildThreadSummaries(List<Message> messages, int? extraRootId = null, int? extraCount = null, DateTime? extraLastReply = null)
    {
        var summaries = messages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .Select(g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)))
            .ToList();

        if (extraRootId is not null && extraCount is not null && extraLastReply is not null)
        {
            var idx = summaries.FindIndex(s => s.RootMessageId == extraRootId.Value);
            if (idx >= 0)
            {
                summaries[idx] = new ThreadSummary(extraRootId.Value, extraCount.Value, extraLastReply.Value);
            }
            else
            {
                summaries.Add(new ThreadSummary(extraRootId.Value, extraCount.Value, extraLastReply.Value));
            }
        }

        return summaries;
    }
}

.chat-layout {
    display: grid;
    grid-template-columns: 20% 1fr;
    height: 100vh;
    overflow: hidden;
}

.chat-layout.thread-open {
    grid-template-columns: 20% 1fr 25%;
}

/* Sidebar */
.channel-sidebar {
    background: #2b2d31;
    color: #f2f3f5;
    padding: 1rem 0;
    overflow-y: auto;
    border-right: 1px solid #1e1f22;
}

.sidebar-title {
    padding: 0 1rem;
    margin: 0 0 0.75rem;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #949ba4;
}

.channel-list {
    display: flex;
    flex-direction: column;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 1rem;
    cursor: pointer;
    border-radius: 4px;
    margin: 0 0.5rem;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #35373c;
}

.channel-item.active {
    background: #404249;
    color: #fff;
}

.channel-name {
    font-weight: 500;
    flex: 1;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.channel-description {
    display: none;
}

.channel-item.active .channel-description,
.channel-item:hover .channel-description {
    display: block;
    font-size: 0.75rem;
    color: #949ba4;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: 120px;
}

.unread-badge {
    background: #f23f43;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 0.1rem 0.4rem;
    border-radius: 8px;
    min-width: 1rem;
    text-align: center;
}

/* Message Area */
.message-area {
    display: flex;
    flex-direction: column;
    height: 100vh;
    background: #313338;
    color: #dbdee1;
}

.channel-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3f4147;
    flex-shrink: 0;
}

.channel-header h2 {
    margin: 0;
    font-size: 1rem;
    color: #f2f3f5;
}

.channel-header p {
    margin: 0.25rem 0 0;
    font-size: 0.8rem;
    color: #949ba4;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.loading-indicator {
    text-align: center;
    padding: 0.5rem;
    color: #949ba4;
    font-size: 0.85rem;
}

/* Message */
.chat-message {
    position: relative;
    padding: 0.5rem 0.75rem;
    border-radius: 4px;
    transition: background 0.1s;
}

.chat-message:hover {
    background: #2e3035;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
    margin-bottom: 0.2rem;
}

.message-author {
    font-weight: 600;
    color: #f2f3f5;
    font-size: 0.9rem;
}

.message-time {
    font-size: 0.75rem;
    color: #949ba4;
}

.message-content {
    font-size: 0.9rem;
    line-height: 1.4;
    word-wrap: break-word;
}

/* Reactions */
.message-reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 0.25rem;
    margin-top: 0.4rem;
}

.reaction-badge {
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 0.15rem 0.4rem;
    font-size: 0.8rem;
    cursor: pointer;
    color: #dbdee1;
    transition: background 0.1s;
}

.reaction-badge:hover {
    background: #404249;
    border-color: #5865f2;
}

/* Thread link */
.thread-link {
    background: none;
    border: none;
    color: #00a8fc;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 0.25rem 0;
    margin-top: 0.25rem;
}

.thread-link:hover {
    text-decoration: underline;
}

/* Hover actions */
.message-actions {
    position: absolute;
    top: -0.5rem;
    right: 0.5rem;
    display: flex;
    gap: 0.25rem;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 0.2rem;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}

.action-btn {
    background: none;
    border: none;
    font-size: 1rem;
    cursor: pointer;
    padding: 0.2rem 0.4rem;
    border-radius: 3px;
    transition: background 0.1s;
}

.action-btn:hover {
    background: #404249;
}

/* Emoji picker */
.emoji-picker {
    position: absolute;
    top: -2.5rem;
    right: 0.5rem;
    display: flex;
    gap: 0.2rem;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 0.3rem;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);
    z-index: 10;
}

.emoji-option {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 0.2rem;
    border-radius: 3px;
    transition: background 0.1s;
}

.emoji-option:hover {
    background: #404249;
}

