    transition: background 0.1s;
}

.chat-message:hover {
    background: #2e3035;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
    margin-bottom: 0.2rem;
}

.message-author {
    font-weight: 600;
    color: #f2f3f5;
    font-size: 0.9rem;
}

.message-time {
    font-size: 0.75rem;
    color: #949ba4;
}

.message-content {
    font-size: 0.9rem;
