    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 0.15rem 0.4rem;
    font-size: 0.8rem;
    cursor: pointer;
    color: #dbdee1;
    transition: background 0.1s;
}

.reaction-badge:hover {
    background: #404249;
    border-color: #5865f2;
}

