    right: 0.5rem;
    display: flex;
    gap: 0.25rem;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 0.2rem;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}

.action-btn {
    background: none;
    border: none;
    font-size: 1rem;
    cursor: pointer;
    padding: 0.2rem 0.4rem;
    border-radius: 3px;
    transition: background 0.1s;
}

.action-btn:hover {
    background: #404249;
}

/* Emoji picker */
.emoji-picker {
    position: absolute;
    top: -2.5rem;
    right: 0.5rem;
    display: flex;
    gap: 0.2rem;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 0.3rem;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);
    z-index: 10;
}

.emoji-option {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 0.2rem;
    border-radius: 3px;
    transition: background 0.1s;
}

.emoji-option:hover {
    background: #404249;
}

/* Message input */
.message-input {
    display: flex;
    align-items: flex-end;
    gap: 0.5rem;
    padding: 0.75rem 1rem;
    border-top: 1px solid #3f4147;
    flex-shrink: 0;
}

.message-input textarea {
    flex: 1;
    background: #383a40;
    border: none;
    border-radius: 8px;
    padding: 0.6rem 1rem;
    color: #dbdee1;
    font-size: 0.9rem;
    resize: none;
    outline: none;
    font-family: inherit;
