    border: none;
    border-radius: 4px;
    padding: 0.6rem 1rem;
    font-size: 0.85rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
}

.send-btn:hover:not(:disabled) {
    background: #4752c4;
}

.send-btn:disabled {
    background: #4752c4;
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread panel */
.thread-panel {
