+    border-radius: 3px;
+    transition: background 0.1s;
+}
+
+.action-btn:hover {
+    background: #404249;
+}
+
+/* Emoji picker */
+.emoji-picker {
+    position: absolute;
+    top: -2.5rem;
+    right: 0.5rem;
+    display: flex;
+    gap: 0.2rem;
+    background: #2b2d31;
+    border: 1px solid #3f4147;
+    border-radius: 4px;
+    padding: 0.3rem;
+    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);
+    z-index: 10;
+}
+
+.emoji-option {
+    background: none;
+    border: none;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 0.2rem;
+    border-radius: 3px;
+    transition: background 0.1s;
+}
+
+.emoji-option:hover {
+    background: #404249;
+}
+
+/* Message input */
+.message-input {
+    display: flex;
+    align-items: flex-end;
+    gap: 0.5rem;
+    padding: 0.75rem 1rem;
+    border-top: 1px solid #3f4147;
+    flex-shrink: 0;
+}
+
+.message-input textarea {
+    flex: 1;
+    background: #383a40;
+    border: none;
+    border-radius: 8px;
+    padding: 0.6rem 1rem;
+    color: #dbdee1;
+    font-size: 0.9rem;
+    resize: none;
+    outline: none;
+    font-family: inherit;
+}
+
+.message-input textarea:focus {
+    box-shadow: 0 0 0 1px #5865f2;
+}
+
+.send-btn {
+    background: #5865f2;
+    color: #fff;
+    border: none;
+    border-radius: 4px;
+    padding: 0.6rem 1rem;
+    font-size: 0.85rem;
+    font-weight: 600;
+    cursor: pointer;
+    transition: background 0.15s;
+}
+
+.send-btn:hover:not(:disabled) {
+    background: #4752c4;
+}
+
+.send-btn:disabled {
+    background: #4752c4;
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* Thread panel */
+.thread-panel {
+    display: flex;
+    flex-direction: column;
+    height: 100vh;
+    background: #2b2d31;
+    color: #dbdee1;
+    border-left: 1px solid #1e1f22;
+}
+
+.thread-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    padding: 0.75rem 1rem;
+    border-bottom: 1px solid #3f4147;
+    flex-shrink: 0;
+}
+
+.thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #f2f3f5;
+}
+
+.close-btn {
+    background: none;
+    border: none;
+    color: #949ba4;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 0.2rem 0.4rem;
+    border-radius: 3px;
+    transition: background 0.1s, color 0.1s;
+}
+
+.close-btn:hover {
+    background: #404249;
+    color: #f2f3f5;
+}
+
+.thread-root-message {
+    padding: 0.75rem 1rem;
+    border-bottom: 1px solid #3f4147;
+    background: #232428;
+}
+
+.thread-root-message .message-author {
+    font-size: 0.85rem;
+}
+
+.thread-root-message .message-content {
+    margin-top: 0.3rem;
+    font-size: 0.85rem;
+    color: #b5bac1;
+}
+
+.thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 0.75rem 1rem;
+    display: flex;
+    flex-direction: column;
+    gap: 0.5rem;
+}
+
+.thread-reply {
+    padding: 0.4rem 0;
+}
+
+.thread-reply .message-content {
+    font-size: 0.85rem;
+}
+

